using Condux.Core.CveScanning;
using Xunit;

namespace Condux.Core.Tests;

/// <summary>
/// The PyPI arm of <see cref="VulnerableRanges"/>. The bulk of it is <c>Golden/pypi-ranges.tsv</c>:
/// real GitHub pip advisory ranges, versions on and around each bound, and the answer Python's own
/// packaging library gives, regenerated by <c>Golden/pypi-ranges.py</c>. The cases written out below
/// name the rules that fixture holds, so a failure there can be read without it.
/// </summary>
public class PypiVulnerableRangesTests
{
    [Theory]
    // GHSA-j8r2-6x86-q33q, requests.
    [InlineData(">= 2.3.0, < 2.31.0", "2.30.0", true)]
    [InlineData(">= 2.3.0, < 2.31.0", "2.31.0", false)]
    // GHSA-v845-jxx5-vc9f, urllib3: the order is numeric, not textual.
    [InlineData("< 1.26.17", "1.26.9", true)]
    [InlineData("< 1.26.17", "1.26.17", false)]
    // GHSA-2xpw-w6gg-jr37, urllib3: a partial bound is the release padded with zeros.
    [InlineData(">= 1.0, < 2.6.0", "1.0.0", true)]
    // GHSA-wvqv-fj8w-qmhm, Django: a pre-release lower bound admits the releases above it.
    [InlineData(">= 6.0a1, < 6.0.8", "6.0", true)]
    [InlineData(">= 6.0a1, < 6.0.8", "5.2.17", false)]
    // GHSA-625g-gx8c-xcmg, Django: "c" is the old spelling of "rc", and a release sorts above both.
    [InlineData(">= 1.7a1, < 1.7c3", "1.7", false)]
    // GHSA-h5c8-rqwp-cp95, jinja2.
    [InlineData("< 3.1.3", "3.1.2", true)]
    // A local label is ignored when matching, so a local build matches as its release.
    [InlineData("<= 2.1.0", "2.1.0+cu118", true)]
    [InlineData("< 2.1.0", "2.1.0+cu118", false)]
    // A post-release orders above its release, and "> V" admits no post-release of V unless V is one.
    [InlineData("<= 1.0", "1.0.post1", false)]
    [InlineData("> 1.0, < 2.0", "1.0.post1", false)]
    [InlineData("> 1.0.post1, < 2.0", "1.0.post2", true)]
    // Nor a local build of V's release, though order alone would admit these.
    [InlineData("> 1.0rc1, < 2.0", "1.0+cu118", false)]
    [InlineData("> 1.0.dev0, < 2.0", "1.0+cu118", false)]
    // GHSA-rf8x-9mhr-49wg, reflex.
    [InlineData("> 0.7.9.post1, < 0.7.10.post1", "0.7.9.post2+cu118", false)]
    [InlineData("> 0.7.9.post1, < 0.7.10.post1", "0.7.9.post2", true)]
    // A local build of a later release is admitted like the release.
    [InlineData("> 1.0rc1, < 2.0", "1.1+cu118", true)]
    [InlineData("> 1.0", "1.0.0.post1", false)]
    [InlineData("> 1.0, < 3.0", "2.0.post1", true)]
    // A release is above its own pre-releases, so "> V" admits it when V is one.
    [InlineData("> 1.0rc1, < 2.0", "1.0", true)]
    // A development release of a post-release sorts below that post-release.
    [InlineData("<= 1.0.post1.dev0", "1.0.post1", false)]
    // An epoch outranks the release.
    [InlineData("< 2.0", "1!1.0", false)]
    // Spellings the specification normalises.
    [InlineData("< 2.0", "v1.0", true)]
    [InlineData("< 2.0", " 1.0 ", true)]
    [InlineData("< 2.0", "1.0-1", true)]
    [InlineData("< 1.7c3", "1.6.9", true)]
    [InlineData("<= 1.0.post1", "1.0rev1", true)]
    [InlineData("<= 1.0.post1", "1.0r1", true)]
    [InlineData("<= 1.0.post1", "1.0_post1", true)]
    // An omitted suffix number is 0, and the separator before it is taken anyway.
    [InlineData("<= 1.0.post0", "1.0.post", true)]
    [InlineData("<= 1.0.post0", "1.0.post-", true)]
    public void DecidesARealPipRange(string range, string version, bool expected) =>
        Assert.Equal(expected, VulnerableRanges.IsConfirmedInRange("pip", range, version));

    /// <summary>Each of these may be vulnerable, and the matcher cannot say, so it must not claim it.</summary>
    [Theory]
    // A pre-release or development running version, inside by plain order.
    [InlineData("< 2.0", "1.5rc1")]
    [InlineData("< 2.0", "1.5.dev3")]
    // A bound with a local label, which only ==, != and === may carry.
    [InlineData("<= 2.1.0+cu118", "2.0.0")]
    // A version the specification does not define.
    [InlineData("< 4.2.0", "4.1.0ubuntu1")]
    [InlineData("< 2.0", "1.0.")]
    [InlineData("< 2.0", "1..0")]
    [InlineData("< 2.0", "1.0+")]
    [InlineData("< 2.0", "1.0+.a")]
    [InlineData("< 2.0", "1.0+a..b")]
    [InlineData("< 2.0", "1.0-")]
    // One separator before a suffix, never two, and a local label is ASCII only.
    [InlineData("< 2.0", "1.0..post1")]
    [InlineData("< 2.0", "1.0.-post1")]
    [InlineData("<= 1.0", "1.0+é")]
    [InlineData("< 2.0", "")]
    public void LeavesWhatItCannotDecideUnconfirmed(string range, string version) =>
        Assert.False(VulnerableRanges.IsConfirmedInRange("pip", range, version));

    [Fact]
    public void RefusesAVersionLongerThanTheCap() =>
        Assert.False(VulnerableRanges.IsConfirmedInRange("pip", "< 2.0", "1." + new string('0', SemanticVersion.MaxLength)));

    /// <summary>
    /// The order itself, which the ranges reach only between a bound and a release. The list is the
    /// specification's own example of suffix ordering without its local versions, which this order
    /// ignores, and with an epoch added at the end; sorted(..., key=Version) in packaging 26.0 returns
    /// it unchanged.
    /// </summary>
    [Fact]
    public void OrdersVersionsAsTheSpecificationDoes()
    {
        string[] ordered =
        [
            "1.dev0", "1.0.dev456", "1.0a1", "1.0a2.dev456", "1.0a12.dev456", "1.0a12", "1.0b1.dev456", "1.0b2",
            "1.0b2.post345.dev456", "1.0b2.post345", "1.0rc1.dev456", "1.0rc1", "1.0", "1.0.post456.dev34",
            "1.0.post456", "1.0.15", "1.1.dev1", "1!0.1",
        ];
        var versions = ordered.Select(text => Pep440Version.Parse(text)!).ToList();

        for (var i = 0; i < versions.Count; i++)
        {
            for (var j = 0; j < versions.Count; j++)
            {
                Assert.True(
                    Math.Sign(versions[i].CompareTo(versions[j])) == i.CompareTo(j),
                    $"{ordered[i]} against {ordered[j]}");
            }
        }
    }

    [Fact]
    public void FoldsTheEcosystemSpelling() =>
        Assert.True(VulnerableRanges.IsConfirmedInRange(" Pip ", "< 2.0", "1.0"));

    /// <summary>
    /// The alternate pre-release words name the same versions as the short ones, which packaging 26.0
    /// confirms (Version("1.0preview1") == Version("1.0rc1")). The ranges cannot show this, since a
    /// pre-release running version is undecided and two bounds' pre-release kinds are never compared.
    /// </summary>
    [Theory]
    [InlineData("1.0alpha1", "1.0a1")]
    [InlineData("1.0beta2", "1.0b2")]
    [InlineData("1.0c1", "1.0rc1")]
    [InlineData("1.0pre1", "1.0rc1")]
    [InlineData("1.0preview1", "1.0rc1")]
    public void ReadsAnAlternatePreReleaseWordAsTheShortOne(string spelled, string canonical) =>
        Assert.Equal(0, Pep440Version.Parse(spelled)!.CompareTo(Pep440Version.Parse(canonical)));

    [Fact]
    public void AgreesWithPackagingOnEveryFixtureRange()
    {
        var result = RangeFixtures.Check("pypi-ranges.tsv", "pip", "packaging");

        // A fixture that failed to load reads exactly like one where every case passed.
        Assert.True(result.Ranges > 1000, $"only {result.Ranges} ranges read");
        Assert.True(result.Versions > 50000, $"only {result.Versions} versions read");
        Assert.True(result.WrongOutside.Count == 0, string.Join('\n', result.WrongOutside.Take(50)));
        // Outside is also decided, not merely never wrong: about half the unclaimed versions, the rest
        // being ones it leaves undecided by design. The floor catches a change that stops deciding it.
        var unclaimed = result.Versions - result.Claimed;
        Assert.True(result.ConfirmedOutside >= unclaimed * 0.4, $"outside {result.ConfirmedOutside} of {unclaimed}");
        // pip has one ordering, packaging's, so the matcher answers exactly as it does.
        var disagreements = result.OverClaims.Concat(result.Undecided).ToList();
        Assert.True(disagreements.Count == 0, string.Join('\n', disagreements.Take(50)));
    }
}
